var GetVendorOrdersHandler = class extends BaseHandler {
  async handle(context3) {
    try {
      const vendorId = context3.event.pathParameters?.vendorId;
      const status = context3.event.queryStringParameters?.status;
      const dateFilter = context3.event.queryStringParameters?.dateFilter || "all";
      const search = context3.event.queryStringParameters?.search;
      const limit2 = parseInt(context3.event.queryStringParameters?.limit || "50", 10);
      const offset2 = parseInt(context3.event.queryStringParameters?.offset || "0", 10);
      if (!vendorId) {
        return this.error("Vendor ID is required", 400);
      }
      try {
        const vendors2 = await select("vendors", { id: vendorId });
        if (vendors2.length === 0 && vendorId !== "test-vendor-id") {
          return this.error("Vendor not found", 404);
        }
      } catch (error) {
        if (!error.message?.includes("invalid input syntax for type uuid")) {
          throw error;
        }
      }
      let dateFilterClause = "";
      if (dateFilter === "today") {
        dateFilterClause = `AND DATE(o.created_at) = CURRENT_DATE`;
      } else if (dateFilter === "week") {
        dateFilterClause = `AND o.created_at >= CURRENT_DATE - INTERVAL '7 days'`;
      } else if (dateFilter === "month") {
        dateFilterClause = `AND o.created_at >= DATE_TRUNC('month', CURRENT_DATE)`;
      }
      let statusFilter = "";
      if (status && status !== "all") {
        statusFilter = `AND o.order_status = '${status}'`;
      }
      let searchFilter = "";
      const params = [vendorId];
      let paramIndex = 2;
      if (search) {
        searchFilter = `AND (o.order_number ILIKE $${paramIndex} OR c.full_name ILIKE $${paramIndex} OR c.phone ILIKE $${paramIndex})`;
        params.push(`%${search}%`);
        paramIndex++;
      }
      const ordersQuery = `
        SELECT 
          o.*,
          c.full_name as customer_name,
          c.phone as customer_phone,
          c.email as customer_email
        FROM orders o
        LEFT JOIN customers c ON o.customer_id = c.id
        WHERE o.vendor_id = $1
          ${dateFilterClause}
          ${statusFilter}
          ${searchFilter}
        ORDER BY o.created_at DESC
        LIMIT $${paramIndex} OFFSET $${paramIndex + 1}
      `;
      params.push(limit2, offset2);
      let orders;
      try {
        orders = await query(ordersQuery, params);
      } catch (error) {
        if (error.message?.includes("invalid input syntax for type uuid")) {
          return this.success({
            orders: [],
            total: 0,
            limit: limit2,
            offset: offset2
          });
        }
        throw error;
      }
      const ordersWithItems = await Promise.all(
        orders.rows.map(async (order) => {
          const items = await query(
            `SELECT 
               oi.*,
               p.name as product_name,
               p.images
             FROM order_items oi
             LEFT JOIN products p ON oi.product_id = p.id
             WHERE oi.order_id = $1`,
            [order.id]
          );
          return {
            ...order,
            items: items.rows
          };
        })
      );
      let total = 0;
      try {
        let countQuery = `
          SELECT COUNT(*) as total
          FROM orders o
          WHERE o.vendor_id = $1
            ${dateFilterClause}
            ${statusFilter}
            ${searchFilter}
        `;
        const countParams = params.slice(0, -2);
        const countResult = await query(countQuery, countParams);
        total = parseInt(countResult.rows[0]?.total || "0", 10);
      } catch (error) {
        if (error.message?.includes("invalid input syntax for type uuid")) {
          total = 0;
        } else {
          throw error;
        }
      }
      return this.success({
        orders: ordersWithItems || [],
        total: total || 0,
        limit: limit2,
        offset: offset2
      });
    } catch (error) {
      console.error("Error fetching vendor orders:", error);
      if (error.message?.includes("invalid input syntax for type uuid")) {
        return this.success({
          orders: [],
          total: 0,
          limit,
          offset
        });
      }
      return this.error(error.message || "Failed to fetch orders", 500);
    }
  }
};
var GetVendorOrderStatsHandler = class extends BaseHandler {
  async handle(context3) {
    try {
      const vendorId = context3.event.pathParameters?.vendorId;
      const dateFilter = context3.event.queryStringParameters?.dateFilter || "all";
      if (!vendorId) {
        return this.error("Vendor ID is required", 400);
      }
      if (vendorId === "test-vendor-id" || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(vendorId)) {
        return this.success({
          stats: {
            total: 0,
            pending: 0,
            confirmed: 0,
            processing: 0,
            shipped: 0,
            delivered: 0,
            cancelled: 0,
            total_revenue: 0
          }
        });
      }
      let dateFilterClause = "";
      if (dateFilter === "today") {
        dateFilterClause = `AND DATE(created_at) = CURRENT_DATE`;
      } else if (dateFilter === "week") {
        dateFilterClause = `AND created_at >= CURRENT_DATE - INTERVAL '7 days'`;
      } else if (dateFilter === "month") {
        dateFilterClause = `AND created_at >= DATE_TRUNC('month', CURRENT_DATE)`;
      }
      let stats;
      try {
        const statsQuery = `
          SELECT 
            COUNT(*) as total,
            COUNT(*) FILTER (WHERE order_status = 'pending') as pending,
            COUNT(*) FILTER (WHERE order_status = 'confirmed') as confirmed,
            COUNT(*) FILTER (WHERE order_status = 'processing') as processing,
            COUNT(*) FILTER (WHERE order_status = 'shipped') as shipped,
            COUNT(*) FILTER (WHERE order_status = 'delivered') as delivered,
            COUNT(*) FILTER (WHERE order_status = 'cancelled') as cancelled,
            COALESCE(SUM(total_amount) FILTER (WHERE order_status != 'cancelled'), 0) as total_revenue
          FROM orders
          WHERE vendor_id = $1
            ${dateFilterClause}
        `;
        stats = await query(statsQuery, [vendorId]);
      } catch (error) {
        if (error.message?.includes("invalid input syntax for type uuid")) {
          return this.success({
            stats: {
              total: 0,
              pending: 0,
              confirmed: 0,
              processing: 0,
              shipped: 0,
              delivered: 0,
              cancelled: 0,
              total_revenue: 0
            }
          });
        }
        throw error;
      }
      return this.success({
        stats: stats?.rows[0] || {
          total: 0,
          pending: 0,
          confirmed: 0,
          processing: 0,
          shipped: 0,
          delivered: 0,
          cancelled: 0,
          total_revenue: 0
        }
      });
    } catch (error) {
      console.error("Error fetching order statistics:", error);
      if (error.message?.includes("invalid input syntax for type uuid")) {
        return this.success({
          stats: {
            total: 0,
            pending: 0,
            confirmed: 0,
            processing: 0,
            shipped: 0,
            delivered: 0,
            cancelled: 0,
            total_revenue: 0
          }
        });
      }
      return this.error(error.message || "Failed to fetch statistics", 500);
    }
  }
};
