// src/endpoints/logistics.ts
init_rds_connection();
var SHIPROCKET_API_BASE = "https://apiv2.shiprocket.in/v1/external";
var shiprocketToken = null;
var tokenExpiryTime = 0;
async function getShiprocketToken() {
  if (shiprocketToken && Date.now() < tokenExpiryTime) {
    return shiprocketToken;
  }
  try {
    const settings = await select("platform_settings", { setting_key: "platform:integrations:shiprocket" });
    const config = settings.length > 0 ? settings[0].setting_value : null;
    if (!config?.email || !config?.password) {
      throw new Error("Shiprocket credentials not configured");
    }
    const response = await fetch(`${SHIPROCKET_API_BASE}/auth/login`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        email: config.email,
        password: config.password
      })
    });
    if (!response.ok) {
      throw new Error("Shiprocket authentication failed");
    }
    const data = await response.json();
    shiprocketToken = data?.token || "";
    if (!shiprocketToken) {
      throw new Error("Shiprocket token missing in response");
    }
    tokenExpiryTime = Date.now() + 10 * 24 * 60 * 60 * 1e3;
    return shiprocketToken;
  } catch (error) {
    console.error("Shiprocket auth error:", error);
    throw error;
  }
}
