// src/endpoints/tier-system.ts
init_rds_connection();
var TIER_CONFIG = {
  Bronze: { commission: 15, minBookings: 0, minRevenue: 0 },
  Silver: { commission: 12, minBookings: 50, minRevenue: 5e4 },
  Gold: { commission: 10, minBookings: 200, minRevenue: 2e5 },
  Platinum: { commission: 8, minBookings: 500, minRevenue: 5e5 }
};
function registerTierSystemEndpoints(app2) {
  app2.get("/vendor/:vendorId/tier", async (c) => {
    try {
      const { vendorId } = c.req.param();
      const vendors2 = await select("vendors", { id: vendorId });
      if (vendors2.length === 0) {
        return c.json({ error: "Vendor not found" }, 404);
      }
      const vendor = vendors2[0];
      const currentTier = vendor.tier || "Bronze";
      const bookings = await query(
        `SELECT COUNT(*) as count, SUM(total_amount) as revenue 
         FROM bookings 
         WHERE vendor_id = $1 AND status = 'completed'`,
        [vendorId]
      ).catch(() => ({ rows: [{ count: "0", revenue: "0" }] }));
      const totalBookings = parseInt(bookings.rows[0]?.count || "0", 10);
      const totalRevenue = parseFloat(bookings.rows[0]?.revenue || "0");
      const tiers = ["Bronze", "Silver", "Gold", "Platinum"];
      const currentTierIndex = tiers.indexOf(currentTier);
      const nextTier = currentTierIndex < tiers.length - 1 ? tiers[currentTierIndex + 1] : null;
      let nextTierEligible = false;
      let nextTierProgress = { bookings: 0, revenue: 0 };
      if (nextTier) {
        const nextTierConfig = TIER_CONFIG[nextTier];
        nextTierEligible = totalBookings >= nextTierConfig.minBookings && totalRevenue >= nextTierConfig.minRevenue;
        nextTierProgress = {
          bookings: Math.min(100, totalBookings / nextTierConfig.minBookings * 100),
          revenue: Math.min(100, totalRevenue / nextTierConfig.minRevenue * 100)
        };
      }
      return c.json({
        success: true,
        tier: {
          current: currentTier,
          commission: TIER_CONFIG[currentTier].commission,
          stats: {
            totalBookings,
            totalRevenue
          },
          nextTier: nextTier ? {
            name: nextTier,
            eligible: nextTierEligible,
            requirements: TIER_CONFIG[nextTier],
            progress: nextTierProgress
          } : null
        }
      });
    } catch (error) {
      console.error("Error fetching vendor tier:", error);
      return c.json({ error: error.message }, 500);
    }
  });
  app2.post("/vendor/:vendorId/tier/upgrade", async (c) => {
    try {
      const { vendorId } = c.req.param();
      const { newTier, adminId } = await c.req.json();
      if (!newTier || !["Bronze", "Silver", "Gold", "Platinum"].includes(newTier)) {
        return c.json({ error: "Invalid tier. Must be Bronze, Silver, Gold, or Platinum" }, 400);
      }
      const vendors2 = await select("vendors", { id: vendorId });
      if (vendors2.length === 0) {
        return c.json({ error: "Vendor not found" }, 404);
      }
      const vendor = vendors2[0];
      const oldTier = vendor.tier || "Bronze";
      const updated = await update(
        "vendors",
        { id: vendorId },
        {
          tier: newTier,
          commission_percentage: TIER_CONFIG[newTier].commission,
          metadata: {
            ...vendor.metadata || {},
            tierHistory: [
              ...vendor.metadata?.tierHistory || [],
              {
                from: oldTier,
                to: newTier,
                upgradedAt: (/* @__PURE__ */ new Date()).toISOString(),
                upgradedBy: adminId
              }
            ]
          }
        }
      );
      return c.json({
        success: true,
        vendor: updated[0],
        message: `Vendor tier upgraded from ${oldTier} to ${newTier}`
      });
    } catch (error) {
      console.error("Error upgrading vendor tier:", error);
      return c.json({ error: error.message }, 500);
    }
  });
  app2.get("/admin/tiers/config", async (c) => {
    return c.json({
      success: true,
      tiers: TIER_CONFIG
    });
  });
  app2.post("/admin/tiers/calculate-commissions", async (c) => {
    try {
      const vendors2 = await select("vendors", { is_active: true });
      const results = vendors2.map((vendor) => {
        const tier = vendor.tier || "Bronze";
        const commission = TIER_CONFIG[tier].commission;
        return {
          vendorId: vendor.id,
          businessName: vendor.business_name,
          currentTier: tier,
          commissionPercentage: commission
        };
      });
      return c.json({
        success: true,
        vendors: results,
        total: results.length
      });
    } catch (error) {
      console.error("Error calculating commissions:", error);
      return c.json({ error: error.message }, 500);
    }
  });
}

// src/endpoints/transaction-monitoring.ts
init_rds_connection();
function getDateRange2(range) {
  const endDate = /* @__PURE__ */ new Date();
  const startDate = /* @__PURE__ */ new Date();
  switch (range) {
    case "1d":
      startDate.setDate(endDate.getDate() - 1);
      break;
    case "7d":
      startDate.setDate(endDate.getDate() - 7);
      break;
    case "30d":
      startDate.setDate(endDate.getDate() - 30);
      break;
    case "90d":
      startDate.setDate(endDate.getDate() - 90);
      break;
    case "1y":
      startDate.setFullYear(endDate.getFullYear() - 1);
      break;
    default:
      startDate.setDate(endDate.getDate() - 7);
  }
  return {
    startDate: startDate.toISOString().split("T")[0],
    endDate: endDate.toISOString().split("T")[0]
  };
}
function registerTransactionMonitoringEndpoints(app2) {
  app2.get("/admin/transactions/stats", async (c) => {
    try {
      const range = c.req.query("range") || "7d";
      const { startDate, endDate } = getDateRange2(range);
      const payments = await query(
        `SELECT * FROM payments 
         WHERE created_at >= $1 AND created_at <= $2`,
        [startDate, endDate]
      ).catch(() => ({ rows: [] }));
      const refunds = await query(
        `SELECT * FROM refunds 
         WHERE created_at >= $1 AND created_at <= $2`,
        [startDate, endDate]
      ).catch(() => ({ rows: [] }));
      const totalTransactions = payments.rows.length;
      const totalVolume = payments.rows.reduce((sum, p) => sum + parseFloat(p.amount || "0"), 0);
      const completedPayments = payments.rows.filter((p) => p.payment_status === "paid");
      const pendingPayments = payments.rows.filter((p) => p.payment_status === "pending");
      const failedPayments = payments.rows.filter((p) => p.payment_status === "failed");
      const successRate = totalTransactions > 0 ? completedPayments.length / totalTransactions * 100 : 0;
      const avgTransactionValue = totalTransactions > 0 ? totalVolume / totalTransactions : 0;
      const stats = {
        totalTransactions,
        totalVolume: Math.round(totalVolume),
        successRate: Math.round(successRate * 10) / 10,
        avgTransactionValue: Math.round(avgTransactionValue),
        pendingCount: pendingPayments.length,
        failedCount: failedPayments.length,
        refundCount: refunds.rows.length,
        range
      };
      return c.json({ success: true, stats });
    } catch (error) {
      console.error("Transaction Stats Error:", error);
      return c.json({ error: error.message }, 500);
    }
  });
  app2.get("/admin/transactions", async (c) => {
    try {
      const page = parseInt(c.req.query("page") || "1", 10);
      const perPage = parseInt(c.req.query("perPage") || "50", 10);
      const status = c.req.query("status") || "all";
      const range = c.req.query("range") || "7d";
      const { startDate, endDate } = getDateRange2(range);
      let queryText = `SELECT * FROM payments 
                       WHERE created_at >= $1 AND created_at <= $2`;
      const params = [startDate, endDate];
      let paramIndex = 3;
      if (status !== "all") {
        queryText += ` AND payment_status = $${paramIndex}`;
        params.push(status);
        paramIndex++;
      }
      queryText += ` ORDER BY created_at DESC LIMIT $${paramIndex} OFFSET $${paramIndex + 1}`;
      params.push(perPage, (page - 1) * perPage);
      const result = await query(queryText, params).catch(() => ({ rows: [] }));
      let countQuery = `SELECT COUNT(*) as count FROM payments 
                        WHERE created_at >= $1 AND created_at <= $2`;
      const countParams = [startDate, endDate];
      if (status !== "all") {
        countQuery += ` AND payment_status = $3`;
        countParams.push(status);
      }
      const countResult = await query(countQuery, countParams).catch(() => ({ rows: [{ count: "0" }] }));
      const totalCount = parseInt(countResult.rows[0]?.count || "0", 10);
      const enrichedTransactions = await Promise.all(
        result.rows.map(async (payment) => {
          let customer = "Unknown";
          let vendor = "Unknown";
          if (payment.customer_id) {
            const customers = await select("customers", { id: payment.customer_id }).catch(() => []);
            if (customers.length > 0) {
              customer = customers[0].full_name || customers[0].phone || "Unknown";
            }
          }
          if (payment.vendor_id) {
            const vendors2 = await select("vendors", { id: payment.vendor_id }).catch(() => []);
            if (vendors2.length > 0) {
              vendor = vendors2[0].business_name || vendors2[0].owner_name || "Unknown";
            }
          }
          let type = "booking";
          if (payment.order_id) type = "order";
          if (payment.subscription_id) type = "subscription";
          return {
            id: payment.id,
            type,
            amount: parseFloat(payment.amount || "0"),
            status: payment.payment_status || "unknown",
            paymentMethod: payment.payment_method || "unknown",
            customer,
            vendor,
            createdAt: payment.created_at || (/* @__PURE__ */ new Date()).toISOString(),
            razorpayId: payment.razorpay_payment_id || payment.razorpay_order_id,
            gateway: payment.payment_method || "razorpay"
          };
        })
      );
      return c.json({
        success: true,
        transactions: enrichedTransactions,
        pagination: {
          page,
          perPage,
          totalCount,
          totalPages: Math.ceil(totalCount / perPage)
        }
      });
    } catch (error) {
      console.error("Get Transactions Error:", error);
      return c.json({ error: error.message }, 500);
    }
  });
  app2.get("/admin/transactions/export", async (c) => {
    try {
      const range = c.req.query("range") || "7d";
      const { startDate, endDate } = getDateRange2(range);
      const payments = await query(
        `SELECT * FROM payments 
         WHERE created_at >= $1 AND created_at <= $2 
         ORDER BY created_at DESC`,
        [startDate, endDate]
      ).catch(() => ({ rows: [] }));
      const headers = ["ID", "Amount", "Status", "Payment Method", "Customer ID", "Vendor ID", "Created At"];
      const rows = payments.rows.map((p) => [
        p.id,
        p.amount,
        p.payment_status,
        p.payment_method,
        p.customer_id,
        p.vendor_id,
        p.created_at
      ]);
      const csv = [
        headers.join(","),
        ...rows.map((row) => row.map((cell) => `"${cell}"`).join(","))
      ].join("\n");
      return c.text(csv, 200, {
        "Content-Type": "text/csv",
        "Content-Disposition": `attachment; filename="transactions-${startDate}-${endDate}.csv"`
      });
    } catch (error) {
      console.error("Export Transactions Error:", error);
      return c.json({ error: error.message }, 500);
    }
  });
}

// src/endpoints/time-window-subscription.ts
init_rds_connection();
var TIME_WINDOWS = [
  { name: "morning", label: "Morning (8 AM - 12 PM)", startHour: 8, endHour: 12 },
  { name: "afternoon", label: "Afternoon (12 PM - 4 PM)", startHour: 12, endHour: 16 },
  { name: "evening", label: "Evening (4 PM - 8 PM)", startHour: 16, endHour: 20 }
];
function registerTimeWindowSubscriptionEndpoints(app2) {
  app2.post("/booking/subscription/time-window", async (c) => {
    try {
      const {
        bookingId,
        customerId,
        providerId,
        serviceType,
        timeWindow,
        recurringSchedule,
        startDate,
        endDate,
        totalSessions
      } = await c.req.json();
      if (!bookingId || !customerId || !serviceType || !timeWindow) {
        return c.json({ error: "Required fields missing" }, 400);
      }
      const validWindows = TIME_WINDOWS.map((w) => w.name);
      if (!validWindows.includes(timeWindow)) {
        return c.json({ error: `Invalid time window. Must be one of: ${validWindows.join(", ")}` }, 400);
      }
      const bookings = await select("bookings", { id: bookingId });
      if (bookings.length === 0) {
        return c.json({ error: "Booking not found" }, 404);
      }
      const vendorId = providerId || bookings[0].vendor_id;
      if (!vendorId) {
        return c.json({ error: "Vendor ID is required for time window subscriptions" }, 400);
      }
      const timeWindowPlan = await insert("subscription_plans", {
        vendor_id: vendorId,
        name: `Time Window Subscription - ${timeWindow}`,
        description: `Custom time window subscription for ${serviceType}`,
        price: 0,
        // Free, pricing handled separately
        interval: "monthly",
        features: [],
        is_active: true
      });
      const subscription = await insert("customer_subscriptions", {
        customer_id: customerId,
        plan_id: timeWindowPlan[0].id,
        vendor_id: vendorId,
        status: "active",
        start_date: startDate || bookings[0].booking_date,
        next_billing_date: endDate || bookings[0].booking_date
      });
      await update(
        "bookings",
        { id: bookingId },
        {
          is_package: true,
          package_details: {
            subscriptionId: subscription[0].id,
            timeWindow,
            recurringSchedule
          }
        }
      );
      return c.json({
        success: true,
        subscription: subscription[0],
        message: "Time window subscription created successfully"
      });
    } catch (error) {
      console.error("Error creating time window subscription:", error);
      return c.json({ error: error.message }, 500);
    }
  });
  app2.get("/subscriptions/time-window/:subscriptionId", async (c) => {
    try {
      const { subscriptionId } = c.req.param();
      const subscriptions = await select("customer_subscriptions", { id: subscriptionId });
      if (subscriptions.length === 0) {
        return c.json({ error: "Subscription not found" }, 404);
      }
      const subscription = subscriptions[0];
      const bookingsResult = await query(
        `SELECT * FROM bookings 
         WHERE package_details->>'subscriptionId' = $1 
         LIMIT 1`,
        [subscriptionId]
      ).catch(() => ({ rows: [] }));
      let timeWindow = null;
      let recurringSchedule = null;
      if (bookingsResult.rows.length > 0 && bookingsResult.rows[0].package_details) {
        const packageDetails = bookingsResult.rows[0].package_details;
        timeWindow = packageDetails.timeWindow;
        recurringSchedule = packageDetails.recurringSchedule;
      }
      return c.json({
        success: true,
        subscription: {
          ...subscription,
          timeWindow,
          recurringSchedule
        }
      });
    } catch (error) {
      console.error("Error fetching time window subscription:", error);
      return c.json({ error: error.message }, 500);
    }
  });
  app2.get("/subscriptions/time-window/customer/:customerId", async (c) => {
    try {
      const { customerId } = c.req.param();
      const subscriptions = await query(
        `SELECT cs.* FROM customer_subscriptions cs
         INNER JOIN bookings b ON b.package_details->>'subscriptionId' = cs.id::text
         WHERE cs.customer_id = $1
         ORDER BY cs.created_at DESC`,
        [customerId]
      ).catch(() => ({ rows: [] }));
      return c.json({
        success: true,
        subscriptions: subscriptions.rows,
        total: subscriptions.rows.length
      });
    } catch (error) {
      console.error("Error fetching customer time window subscriptions:", error);
      return c.json({ error: error.message }, 500);
    }
  });
  app2.get("/subscriptions/time-window/windows", async (c) => {
    return c.json({
      success: true,
      windows: TIME_WINDOWS
    });
  });
}

// src/endpoints/storage.ts
var import_client_s34 = require("@aws-sdk/client-s3");
var import_s3_request_presigner2 = require("@aws-sdk/s3-request-presigner");
var s3Client3 = new import_client_s34.S3Client({ region: process.env.AWS_REGION || "ap-south-1" });
var BUCKET_NAME2 = process.env.S3_BUCKET_NAME || "warmpawz-storage";
function registerStorageEndpoints(app2) {
  app2.post("/storage/upload", async (c) => {
    try {
      const formData = await c.req.formData();
      const file = formData.get("file");
      const vendorId = formData.get("vendorId");
      const documentType = formData.get("documentType");
      if (!file || !vendorId || !documentType) {
        return c.json({ error: "Missing required fields: file, vendorId, documentType" }, 400);
      }
      console.log(`\u{1F4E4} Uploading file: ${file.name} for vendor: ${vendorId}`);
      const timestamp = Date.now();
      const fileExt = file.name.split(".").pop();
      const fileName = `${vendorId}/${documentType}_${timestamp}.${fileExt}`;
      const arrayBuffer = await file.arrayBuffer();
      const uint8Array = new Uint8Array(arrayBuffer);
      await s3Client3.send(new import_client_s34.PutObjectCommand({
        Bucket: BUCKET_NAME2,
        Key: fileName,
        Body: uint8Array,
        ContentType: file.type
      }));
      console.log("\u2705 File uploaded successfully:", fileName);
      const signedUrl = await (0, import_s3_request_presigner2.getSignedUrl)(
        s3Client3,
        new import_client_s34.GetObjectCommand({
          Bucket: BUCKET_NAME2,
          Key: fileName
        }),
        { expiresIn: 31536e3 }
        // 1 year in seconds
      );
      return c.json({
        success: true,
        fileName,
        url: signedUrl,
        publicUrl: signedUrl
      });
    } catch (error) {
      console.error("\u274C Error uploading file:", error);
      return c.json({ error: error.message }, 500);
    }
  });
  app2.post("/storage/upload-multiple", async (c) => {
    try {
      const formData = await c.req.formData();
      const vendorId = formData.get("vendorId");
      if (!vendorId) {
        return c.json({ error: "Vendor ID is required" }, 400);
      }
      const uploadResults = [];
      const entries = Array.from(formData.entries());
      for (const [key, value] of entries) {
        if (value instanceof File && key !== "vendorId") {
          const file = value;
          const documentType = key;
          console.log(`\u{1F4E4} Uploading: ${documentType} - ${file.name}`);
          try {
            const timestamp = Date.now();
            const random = Math.random().toString(36).substring(2, 11);
            const fileExt = file.name.split(".").pop();
            const fileName = `${vendorId}/${documentType}_${timestamp}_${random}.${fileExt}`;
            const arrayBuffer = await file.arrayBuffer();
            const uint8Array = new Uint8Array(arrayBuffer);
            await s3Client3.send(new import_client_s34.PutObjectCommand({
              Bucket: BUCKET_NAME2,
              Key: fileName,
              Body: uint8Array,
              ContentType: file.type
            }));
            const signedUrl = await (0, import_s3_request_presigner2.getSignedUrl)(
              s3Client3,
              new import_client_s34.GetObjectCommand({
                Bucket: BUCKET_NAME2,
                Key: fileName
              }),
              { expiresIn: 31536e3 }
            );
            uploadResults.push({
              documentType,
              success: true,
              fileName,
              originalName: file.name,
              url: signedUrl,
              type: file.type.startsWith("image/") ? "image" : "document"
            });
            console.log(`\u2705 Uploaded: ${documentType}`);
          } catch (error) {
            console.error(`\u274C Upload error for ${documentType}:`, error);
            uploadResults.push({
              documentType,
              success: false,
              error: error.message
            });
          }
        }
      }
      return c.json({
        success: true,
        uploads: uploadResults,
        total: uploadResults.length,
        successful: uploadResults.filter((r) => r.success).length
      });
    } catch (error) {
      console.error("\u274C Error uploading multiple files:", error);
      return c.json({ error: error.message }, 500);
    }
  });
  app2.delete("/storage/file/:fileKey", async (c) => {
    try {
      const { fileKey } = c.req.param();
      const decodedKey = decodeURIComponent(fileKey);
      await s3Client3.send(new import_client_s34.DeleteObjectCommand({
        Bucket: BUCKET_NAME2,
        Key: decodedKey
      }));
      return c.json({
        success: true,
        message: "File deleted successfully"
      });
    } catch (error) {
      console.error("\u274C Error deleting file:", error);
      return c.json({ error: error.message }, 500);
    }
  });
  app2.get("/storage/presigned-url", async (c) => {
    try {
      const fileKey = c.req.query("fileKey");
      const expiresIn = parseInt(c.req.query("expiresIn") || "3600", 10);
      if (!fileKey) {
        return c.json({ error: "fileKey is required" }, 400);
      }
      const signedUrl = await (0, import_s3_request_presigner2.getSignedUrl)(
        s3Client3,
        new import_client_s34.GetObjectCommand({
          Bucket: BUCKET_NAME2,
          Key: fileKey
        }),
        { expiresIn }
      );
      return c.json({
        success: true,
        url: signedUrl,
        expiresIn
      });
    } catch (error) {
      console.error("\u274C Error generating presigned URL:", error);
      return c.json({ error: error.message }, 500);
    }
  });
  app2.post("/storage/upload-media", async (c) => {
    try {
      const formData = await c.req.formData();
      const file = formData.get("file");
      const userId = formData.get("userId");
      const userType = formData.get("userType");
      const folder = formData.get("folder") || "media";
      if (!file || !userId || !userType) {
        return c.json({ error: "Missing required fields: file, userId, userType" }, 400);
      }
      console.log(`\u{1F4E4} Uploading ${userType} photo: ${file.name} for ${userId}`);
      const timestamp = Date.now();
      const random = Math.random().toString(36).substring(2, 11);
      const fileExt = file.name.split(".").pop() || "jpg";
      const fileName = `${folder}/${userType}/${userId}_${timestamp}_${random}.${fileExt}`;
      const arrayBuffer = await file.arrayBuffer();
      const uint8Array = new Uint8Array(arrayBuffer);
      await s3Client3.send(new import_client_s34.PutObjectCommand({
        Bucket: BUCKET_NAME2,
        Key: fileName,
        Body: uint8Array,
        ContentType: file.type
      }));
      console.log("\u2705 Media uploaded successfully:", fileName);
      const signedUrl = await (0, import_s3_request_presigner2.getSignedUrl)(
        s3Client3,
        new import_client_s34.GetObjectCommand({
          Bucket: BUCKET_NAME2,
          Key: fileName
        }),
        { expiresIn: 31536e3 }
        // 1 year in seconds
      );
      const publicUrl = `https://${BUCKET_NAME2}.s3.${process.env.AWS_REGION || "ap-south-1"}.amazonaws.com/${fileName}`;
      return c.json({
        success: true,
        fileName,
        url: signedUrl,
        publicUrl,
        key: fileName
      });
    } catch (error) {
      console.error("\u274C Error uploading media:", error);
      return c.json({ error: error.message }, 500);
    }
  });
}

