function registerAdminGovernanceEnhancedEndpoints(app2) {
  const refreshCapabilitiesHandler = new RefreshCapabilitiesHandler();
  const syncCatalogHandler = new SyncServiceCatalogHandler();
  const applyTierHandler = new ApplyTierCommissionsHandler();
  const calculateTaxHandler = new CalculateTaxHandler();
  const getBannersHandler = new GetBannersHandler();
  const createBannerHandler = new CreateBannerHandler();
  const updateBannerHandler = new UpdateBannerHandler();
  const deleteBannerHandler = new DeleteBannerHandler();
  app2.post("/admin/capabilities/refresh", async (c) => {
    const event = createApiGatewayEvent21(c.req);
    const context3 = createLambdaContext21();
    const result = await refreshCapabilitiesHandler.execute(event, context3);
    return c.json(JSON.parse(result.body), result.statusCode);
  });
  app2.post("/admin/service-catalog/sync", async (c) => {
    const event = createApiGatewayEvent21(c.req);
    const context3 = createLambdaContext21();
    const result = await syncCatalogHandler.execute(event, context3);
    return c.json(JSON.parse(result.body), result.statusCode);
  });
  app2.post("/admin/tiers/apply-commissions", async (c) => {
    const event = createApiGatewayEvent21(c.req);
    const context3 = createLambdaContext21();
    const result = await applyTierHandler.execute(event, context3);
    return c.json(JSON.parse(result.body), result.statusCode);
  });
  app2.post("/admin/tax/calculate", async (c) => {
    try {
      const body2 = await c.req.json();
      const { amount, gstRate, cgstRate, sgstRate, igstRate } = body2;
      if (!amount || !gstRate) {
        return c.json({ error: "amount and gstRate are required" }, 400);
      }
      const baseAmount = parseFloat(amount);
      const gst = baseAmount * parseFloat(gstRate) / 100;
      const total = baseAmount + gst;
      let cgst = 0;
      let sgst = 0;
      let igst = 0;
      if (cgstRate && sgstRate) {
        cgst = baseAmount * parseFloat(cgstRate) / 100;
        sgst = baseAmount * parseFloat(sgstRate) / 100;
      } else if (igstRate) {
        igst = baseAmount * parseFloat(igstRate) / 100;
      }
      return c.json({
        success: true,
        taxCalculation: {
          baseAmount,
          gst,
          cgst,
          sgst,
          igst,
          total
        }
      });
    } catch (error) {
      console.error("Error calculating tax:", error);
      return c.json({ error: error.message || "Failed to calculate tax" }, 500);
    }
  });
  app2.get("/admin/banners", async (c) => {
    try {
      const event = createApiGatewayEvent21(c.req);
      event.queryStringParameters = Object.fromEntries(new URL(c.req.url, "http://localhost").searchParams);
      const context3 = createLambdaContext21();
      const result = await getBannersHandler.execute(event, context3);
      return c.json(JSON.parse(result.body), result.statusCode);
    } catch (error) {
      if (error.message && error.message.includes("does not exist")) {
        console.warn("\u26A0\uFE0F banners table does not exist - returning empty array");
        return c.json({ success: true, banners: [], total: 0, message: "Banners table not initialized. Run migrations first." });
      }
      return c.json({ error: error.message }, 500);
    }
  });
  app2.post("/admin/banners", async (c) => {
    const event = createApiGatewayEvent21(c.req);
    const context3 = createLambdaContext21();
    const result = await createBannerHandler.execute(event, context3);
    return c.json(JSON.parse(result.body), result.statusCode);
  });
  app2.put("/admin/banners/:id", async (c) => {
    const event = createApiGatewayEvent21(c.req);
    event.pathParameters = { id: c.req.param("id") };
    const context3 = createLambdaContext21();
    const result = await updateBannerHandler.execute(event, context3);
    return c.json(JSON.parse(result.body), result.statusCode);
  });
  app2.delete("/admin/banners/:id", async (c) => {
    const event = createApiGatewayEvent21(c.req);
    event.pathParameters = { id: c.req.param("id") };
    const context3 = createLambdaContext21();
    const result = await deleteBannerHandler.execute(event, context3);
    return c.json(JSON.parse(result.body), result.statusCode);
  });
}
function createApiGatewayEvent21(req) {
  return {
    httpMethod: req.method,
    path: req.url,
    headers: Object.fromEntries(req.headers || []),
    body: JSON.stringify(req.body || {}),
    pathParameters: {},
    queryStringParameters: Object.fromEntries(new URL(req.url, "http://localhost").searchParams),
    requestContext: {
      requestId: crypto.randomUUID()
    }
  };
}
function createLambdaContext21() {
  return {
    requestId: crypto.randomUUID(),
    functionName: "admin-governance-enhanced",
    functionVersion: "$LATEST"
  };
}

