// src/endpoints/customer-appointments.ts
init_base_handler();
init_rds_connection();
var GetCustomerAppointmentsHandler = class extends BaseHandler {
  async handle(context3) {
    try {
      const customerId = context3.event.pathParameters?.customerId || context3.event.queryStringParameters?.customerId || context3.userId;
      if (!customerId) {
        return this.error("Customer ID is required", 401);
      }
      const appointments = await query(`
        SELECT 
          a.id,
          a.booking_id,
          a.appointment_date,
          a.appointment_time,
          a.status,
          a.notes,
          a.created_at,
          a.updated_at,
          b.service_id,
          b.vendor_id,
          b.pet_id,
          s.name as service_name,
          s.service_style,
          v.name as vendor_name,
          v.address as vendor_address,
          p.name as pet_name
        FROM appointments a
        INNER JOIN bookings b ON a.booking_id = b.id
        LEFT JOIN services s ON b.service_id = s.id
        LEFT JOIN vendors v ON b.vendor_id = v.id
        LEFT JOIN pets p ON b.pet_id = p.id
        WHERE b.customer_id = $1
        ORDER BY a.appointment_date DESC, a.appointment_time DESC
      `, [customerId]);
      return this.success({
        appointments: appointments.rows,
        count: appointments.rows.length
      });
    } catch (error) {
      console.error("Error fetching customer appointments:", error);
      return this.error(error.message || "Failed to fetch appointments", 500);
    }
  }
};
