// src/endpoints/admin-sellers.ts
init_rds_connection();
init_base_handler();
var GetSellersHandler = class extends BaseHandler {
  async handle(context3) {
    try {
      const status = context3.event.queryStringParameters?.status || "pending";
      const limit2 = parseInt(context3.event.queryStringParameters?.limit || "50", 10);
      const offset2 = parseInt(context3.event.queryStringParameters?.offset || "0", 10);
      const sellersQuery = `
        SELECT 
          v.*,
          r.name as role_name,
          r.id as role_id
        FROM vendors v
        LEFT JOIN roles r ON v.role_id = r.id
        WHERE (
          r.name = 'product_seller' OR 
          r.name = 'pet_product_seller' OR
          v.seller_status IS NOT NULL
        )
        ${status !== "all" ? `AND v.seller_status = $1` : ""}
        ORDER BY v.created_at DESC
        LIMIT $${status !== "all" ? 2 : 1} OFFSET $${status !== "all" ? 3 : 2}
      `;
      const params = [];
      if (status !== "all") {
        params.push(status);
      }
      params.push(limit2, offset2);
      const sellers = await query(sellersQuery, params);
      const countQuery = `
        SELECT COUNT(*) as total
        FROM vendors v
        LEFT JOIN roles r ON v.role_id = r.id
        WHERE (
          r.name = 'product_seller' OR 
          r.name = 'pet_product_seller' OR
          v.seller_status IS NOT NULL
        )
        ${status !== "all" ? `AND v.seller_status = $1` : ""}
      `;
      const countParams = status !== "all" ? [status] : [];
      const countResult = await query(countQuery, countParams);
      const total = parseInt(countResult.rows[0]?.total || "0", 10);
      return this.success({
        sellers: sellers.rows,
        total,
        limit: limit2,
        offset: offset2
      });
    } catch (error) {
      console.error("Error fetching sellers:", error);
      return this.error(error.message || "Failed to fetch sellers", 500);
    }
  }
};
var ApproveSellerHandler = class extends BaseHandler {
  async handle(context3) {
    try {
      const vendorId = context3.event.pathParameters?.vendorId;
      const body2 = this.parseBody(context3.event);
      const adminId = context3.userId || body2.adminId;
      if (!vendorId) {
        return this.error("Vendor ID is required", 400);
      }
      const vendors2 = await select("vendors", { id: vendorId });
      if (vendors2.length === 0) {
        return this.error("Vendor not found", 404);
      }
      const vendor = vendors2[0];
      await update("vendors", { id: vendorId }, {
        seller_status: "approved",
        seller_approved_at: (/* @__PURE__ */ new Date()).toISOString(),
        seller_approved_by: adminId,
        seller_rejection_reason: null
      });
      await query(
        `INSERT INTO notifications (recipient_id, recipient_type, notification_type, title, message, channels, is_read)
         VALUES ($1, 'vendor', 'seller_approved', $2, $3, $4, false)`,
        [
          vendorId,
          "Seller Application Approved",
          "Your seller application has been approved! You can now manage products and receive orders.",
          JSON.stringify({ email: true, sms: true, inApp: true, push: false })
        ]
      ).catch((err) => console.error("Failed to create notification:", err));
      return this.success({
        message: "Seller approved successfully",
        vendorId
      });
    } catch (error) {
      console.error("Error approving seller:", error);
      return this.error(error.message || "Failed to approve seller", 500);
    }
  }
};
var RejectSellerHandler = class extends BaseHandler {
  async handle(context3) {
    try {
      const vendorId = context3.event.pathParameters?.vendorId;
      const body2 = this.parseBody(context3.event);
      const adminId = context3.userId || body2.adminId;
      const reason = body2.reason || "Application rejected";
      if (!vendorId) {
        return this.error("Vendor ID is required", 400);
      }
      const vendors2 = await select("vendors", { id: vendorId });
      if (vendors2.length === 0) {
        return this.error("Vendor not found", 404);
      }
      await update("vendors", { id: vendorId }, {
        seller_status: "rejected",
        seller_approved_at: null,
        seller_approved_by: null,
        seller_rejection_reason: reason
      });
      await query(
        `INSERT INTO notifications (recipient_id, recipient_type, notification_type, title, message, channels, is_read)
         VALUES ($1, 'vendor', 'seller_rejected', $2, $3, $4, false)`,
        [
          vendorId,
          "Seller Application Rejected",
          `Your seller application has been rejected. Reason: ${reason}`,
          JSON.stringify({ email: true, sms: true, inApp: true, push: false })
        ]
      ).catch((err) => console.error("Failed to create notification:", err));
      return this.success({
        message: "Seller rejected successfully",
        vendorId
      });
    } catch (error) {
      console.error("Error rejecting seller:", error);
      return this.error(error.message || "Failed to reject seller", 500);
    }
  }
};
function registerAdminSellersEndpoints(app2) {
  const getSellersHandler = new GetSellersHandler();
  const approveSellerHandler = new ApproveSellerHandler();
  const rejectSellerHandler = new RejectSellerHandler();
  app2.get("/admin/vendors/sellers", async (c) => {
    const response = await getSellersHandler.handle({
      event: {
        queryStringParameters: Object.fromEntries(c.req.query())
      }
    });
    return c.json(response.body, response.statusCode);
  });
  app2.post("/admin/vendors/:vendorId/approve-seller", async (c) => {
    const response = await approveSellerHandler.handle({
      event: {
        pathParameters: c.req.param(),
        body: await c.req.json()
      }
    });
    return c.json(response.body, response.statusCode);
  });
  app2.post("/admin/vendors/:vendorId/reject-seller", async (c) => {
    const response = await rejectSellerHandler.handle({
      event: {
        pathParameters: c.req.param(),
        body: await c.req.json()
      }
    });
    return c.json(response.body, response.statusCode);
  });
}

