// src/utils/bedrock-client.ts
var import_client_bedrock_runtime = require("@aws-sdk/client-bedrock-runtime");
init_rds_connection();
async function getBedrockConfig() {
  try {
    const settingsResult = await query(
      `SELECT setting_value FROM platform_settings WHERE setting_key = 'aws_config' LIMIT 1`
    );
    const awsSettings = settingsResult.rows[0]?.setting_value || null;
    if (!awsSettings?.bedrock?.enabled) {
      console.warn("AWS Bedrock is not enabled in platform settings");
      return null;
    }
    if (!awsSettings.credentials?.accessKeyId || !awsSettings.credentials?.secretAccessKey) {
      throw new Error("AWS credentials not configured");
    }
    let modelId = awsSettings.bedrock.modelId || "us.amazon.nova-lite-v1:0";
    if (modelId === "amazon.nova-lite-v1:0") {
      modelId = "us.amazon.nova-lite-v1:0";
    }
    let region = (awsSettings.bedrock.region || "ap-south-1").trim();
    if (modelId.startsWith("us.") && region === "ap-south-1") {
      region = "us-east-1";
    }
    const client2 = new import_client_bedrock_runtime.BedrockRuntimeClient({
      region,
      credentials: {
        accessKeyId: String(awsSettings.credentials.accessKeyId).trim(),
        secretAccessKey: String(awsSettings.credentials.secretAccessKey).trim()
      }
    });
    return { client: client2, modelId, region };
  } catch (error) {
    console.error("Error getting Bedrock config:", error);
    return null;
  }
}
async function invokeBedrock(prompt, systemPrompt, options = {}) {
  const config = await getBedrockConfig();
  if (!config) {
    throw new Error("Bedrock is not configured or enabled");
  }
  const { client: client2, modelId } = config;
  const { maxTokens = 1024, temperature = 0.5, topP = 0.9 } = options;
  try {
    let body2;
    if (modelId.includes("claude") || modelId.includes("anthropic")) {
      const messages = [];
      if (systemPrompt) {
        messages.push({
          role: "system",
          content: systemPrompt
        });
      }
      messages.push({
        role: "user",
        content: prompt
      });
      body2 = {
        anthropic_version: "bedrock-2023-05-31",
        max_tokens: maxTokens,
        temperature,
        top_p: topP,
        messages
      };
    } else if (modelId.includes("nova") || modelId.includes("amazon")) {
      const inputText = systemPrompt ? `System: ${systemPrompt}

Human: ${prompt}

Assistant:` : `Human: ${prompt}

Assistant:`;
      body2 = {
        inputText,
        textGenerationConfig: {
          maxTokenCount: maxTokens,
          temperature,
          topP
        }
      };
    } else {
      const messages = [];
      if (systemPrompt) {
        messages.push({
          role: "system",
          content: systemPrompt
        });
      }
      messages.push({
        role: "user",
        content: prompt
      });
      body2 = {
        anthropic_version: "bedrock-2023-05-31",
        max_tokens: maxTokens,
        temperature,
        top_p: topP,
        messages
      };
    }
    const command = new import_client_bedrock_runtime.InvokeModelCommand({
      modelId,
      body: JSON.stringify(body2),
      contentType: "application/json",
      accept: "application/json"
    });
    const response = await client2.send(command);
    const responseBody = JSON.parse(new TextDecoder().decode(response.body));
    if (modelId.includes("nova") || modelId.includes("amazon")) {
      if (responseBody.results && responseBody.results.length > 0) {
        return responseBody.results[0].outputText;
      }
    } else {
      if (responseBody.content && responseBody.content.length > 0) {
        return responseBody.content[0].text;
      }
    }
    throw new Error("Invalid response format from Bedrock");
  } catch (error) {
    console.error("Error invoking Bedrock:", error);
    throw new Error(`Bedrock invocation failed: ${error.message}`);
  }
}

// src/utils/error-recovery.ts
init_rds_connection();
var DEFAULT_RETRY_OPTIONS = {
  maxAttempts: 3,
  initialDelayMs: 1e3,
  maxDelayMs: 3e4,
  backoffMultiplier: 2,
  retryableErrors: ["ETIMEDOUT", "ECONNRESET", "ENOTFOUND", "EAI_AGAIN"]
};
async function withRetry(fn, options = {}) {
  const opts = { ...DEFAULT_RETRY_OPTIONS, ...options };
  let lastError = null;
  for (let attempt = 1; attempt <= opts.maxAttempts; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;
      const isRetryable = opts.retryableErrors.some(
        (code) => error.code === code || error.message?.includes(code)
      );
      if (!isRetryable || attempt === opts.maxAttempts) {
        throw error;
      }
      const delay = Math.min(
        opts.initialDelayMs * Math.pow(opts.backoffMultiplier, attempt - 1),
        opts.maxDelayMs
      );
      console.log(`[RETRY] Attempt ${attempt} failed, retrying in ${delay}ms...`);
      await sleep(delay);
    }
  }
  throw lastError || new Error("All retry attempts failed");
}
function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

