var GetTransactionsHandler = class extends BaseHandler {
  async handle(context3) {
    try {
      const params = context3.event.queryStringParameters || {};
      const limit2 = parseInt(params.limit || "50", 10);
      const offset2 = parseInt(params.offset || "0", 10);
      let transactions, total;
      try {
        transactions = await query(`
          SELECT 
            t.*,
            b.id as booking_id,
            o.id as order_id,
            v.business_name as vendor_name,
            c.name as customer_name
          FROM transactions t
          LEFT JOIN bookings b ON b.id = t.booking_id
          LEFT JOIN orders o ON o.id = t.order_id
          LEFT JOIN vendors v ON v.id = t.vendor_id
          LEFT JOIN customers c ON c.id = t.customer_id
          ORDER BY t.created_at DESC
          LIMIT $1 OFFSET $2
        `, [limit2, offset2]);
        total = await query(`SELECT COUNT(*) as count FROM transactions`);
      } catch {
        const bookingTransactions = await query(`
          SELECT 
            b.id as transaction_id,
            b.total_amount as amount,
            b.payment_status as status,
            b.created_at,
            b.id as booking_id,
            v.business_name as vendor_name,
            c.name as customer_name
          FROM bookings b
          LEFT JOIN vendors v ON v.id = b.vendor_id
          LEFT JOIN customers c ON c.id = b.customer_id
          WHERE b.payment_status = 'paid'
          ORDER BY b.created_at DESC
          LIMIT $1 OFFSET $2
        `, [limit2, offset2]).catch(() => ({ rows: [] }));
        transactions = bookingTransactions;
        total = await query(`SELECT COUNT(*) as count FROM bookings WHERE payment_status = 'paid'`).catch(() => ({ rows: [{ count: "0" }] }));
      }
      const formattedTransactions = (transactions.rows || []).map((t) => ({
        ...t,
        id: String(t.id || t.transaction_id || ""),
        transactionId: String(t.transaction_id || t.id || ""),
        amount: parseFloat(t.amount || "0"),
        status: String(t.status || "pending"),
        vendorName: String(t.vendor_name || ""),
        customerName: String(t.customer_name || ""),
        bookingId: String(t.booking_id || ""),
        orderId: String(t.order_id || ""),
        createdAt: String(t.created_at || (/* @__PURE__ */ new Date()).toISOString())
      }));
      return this.success({
        success: true,
        transactions: formattedTransactions,
        total: parseInt(total?.rows[0]?.count || "0", 10),
        limit: limit2,
        offset: offset2
      });
    } catch (error) {
      console.error("Error fetching transactions:", error);
      return this.success({ success: true, transactions: [], total: 0, limit: 50, offset: 0 });
    }
  }
};
var GetTransactionStatsHandler = class extends BaseHandler {
  async handle(context3) {
    try {
      const stats = await query(`
        SELECT 
          COUNT(*) as total_transactions,
          COUNT(*) FILTER (WHERE status = 'success') as successful_transactions,
          COUNT(*) FILTER (WHERE status = 'failed') as failed_transactions,
          COALESCE(SUM(amount) FILTER (WHERE status = 'success'), 0) as total_amount,
          COALESCE(SUM(amount) FILTER (WHERE transaction_date >= DATE_TRUNC('day', CURRENT_DATE)), 0) as today_amount,
          COALESCE(SUM(amount) FILTER (WHERE transaction_date >= DATE_TRUNC('month', CURRENT_DATE)), 0) as this_month_amount
        FROM transactions
      `);
      return this.success({ success: true, stats: stats.rows[0] });
    } catch (error) {
      return this.error(error.message || "Failed to fetch transaction stats", 500);
    }
  }
};
var ExportTransactionsHandler = class extends BaseHandler {
  async handle(context3) {
    try {
      const params = context3.event.queryStringParameters || {};
      const format = params.format || "csv";
      const transactions = await query(`
        SELECT 
          t.*,
          v.business_name as vendor_name,
          c.name as customer_name
        FROM transactions t
        LEFT JOIN vendors v ON v.id = t.vendor_id
        LEFT JOIN customers c ON c.id = t.customer_id
        ORDER BY t.created_at DESC
      `);
      const rows = transactions.rows || [];
      if (format === "csv") {
        if (rows.length === 0) {
          return this.success({
            success: true,
            exportData: "",
            format: "csv",
            filename: `transactions-${(/* @__PURE__ */ new Date()).toISOString().split("T")[0]}.csv`
          });
        }
        const headers = Object.keys(rows[0]).join(",");
        const csvRows = rows.map(
          (row) => Object.values(row).map((v) => `"${String(v || "").replace(/"/g, '""')}"`).join(",")
        );
        const csv = [headers, ...csvRows].join("\n");
        return this.success({
          success: true,
          exportData: csv,
          format: "csv",
          filename: `transactions-${(/* @__PURE__ */ new Date()).toISOString().split("T")[0]}.csv`
        });
      }
      return this.success({ success: true, transactions: rows });
    } catch (error) {
      console.error("Error exporting transactions:", error);
      return this.success({
        success: true,
        exportData: "",
        format: "csv",
        filename: `transactions-${(/* @__PURE__ */ new Date()).toISOString().split("T")[0]}.csv`
      });
    }
  }
};
