var GetUsersHandler = class extends BaseHandler {
  async handle(context3) {
    try {
      const params = context3.event.queryStringParameters || {};
      const role = params.role;
      const limit2 = parseInt(params.limit || "50", 10);
      const offset2 = parseInt(params.offset || "0", 10);
      let users;
      if (role === "admin") {
        users = await query(`
          SELECT * FROM admins
          ORDER BY created_at DESC
          LIMIT $1 OFFSET $2
        `, [limit2, offset2]);
      } else if (role === "vendor") {
        users = await query(`
          SELECT id, email, business_name as name, phone, status, created_at
          FROM vendors
          ORDER BY created_at DESC
          LIMIT $1 OFFSET $2
        `, [limit2, offset2]);
      } else {
        users = await query(`
          SELECT id, email, name, phone, created_at
          FROM customers
          ORDER BY created_at DESC
          LIMIT $1 OFFSET $2
        `, [limit2, offset2]);
      }
      return this.success({ success: true, users: users.rows });
    } catch (error) {
      return this.error(error.message || "Failed to fetch users", 500);
    }
  }
};
